const getCookie=(r,n)=>{for(const p of (r.headers.get("Cookie")||"").split(";")){const i=p.indexOf("=");if(i>0&&p.slice(0,i).trim()===n)return p.slice(i+1).trim();}return null;};
const cookie=t=>"__Host-nexchat_session="+t+"; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=2592000";
const originOK=r=>!r.headers.get("Origin")||r.headers.get("Origin")===new URL(r.url).origin;
async function limit(env,key,max,secs){const now=Math.floor(Date.now()/1000);await env.DB.prepare("INSERT INTO auth_rate_limits(bucket_key,window_start,attempts) VALUES(?,?,1) ON CONFLICT(bucket_key) DO UPDATE SET attempts=CASE WHEN window_start<? THEN 1 ELSE attempts+1 END,window_start=CASE WHEN window_start<? THEN excluded.window_start ELSE window_start END").bind(key,now,now-secs,now-secs).run();const x=await env.DB.prepare("SELECT attempts FROM auth_rate_limits WHERE bucket_key=?").bind(key).first();return (x?.attempts||0)<=max;}
async function session(env,id,request){const raw=crypto.getRandomValues(new Uint8Array(32));const token=b64(raw).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,"");const tokenHash=await sha(token),ua=String(request?.headers.get("User-Agent")||"").slice(0,400),ip=String(request?.headers.get("CF-Connecting-IP")||"unknown");let device="متصفح غير معروف";if(/Android/i.test(ua))device="Android";else if(/iPhone|iPad/i.test(ua))device="iPhone/iPad";else if(/Windows/i.test(ua))device="Windows";else if(/Macintosh|Mac OS/i.test(ua))device="Mac";else if(/Linux/i.test(ua))device="Linux";await env.DB.prepare("INSERT INTO sessions(token_hash,user_id,expires_at) VALUES(?,?,?)").bind(tokenHash,id,new Date(Date.now()+2592000000).toISOString()).run();await env.DB.prepare("INSERT INTO session_devices(token_hash,user_id,device_name,user_agent,ip_hash) VALUES(?,?,?,?,?)").bind(tokenHash,id,device,ua,await sha(ip)).run();await env.DB.prepare("INSERT INTO activity_log(id,user_id,event_type,detail,ip_hash) VALUES(?,?,?,?,?)").bind(crypto.randomUUID(),id,"login","تسجيل دخول من "+device,await sha(ip)).run();return token;}
async function current(r,env){const t=getCookie(r,"__Host-nexchat_session");if(!t||t.length>100)return null;const h=await sha(t);const u=await env.DB.prepare("SELECT u.id,u.username,u.email,u.display_name,u.avatar_key,u.bio,u.city,u.service,u.is_public,u.cover_key,u.contact_password_salt,u.contact_password_hash,u.created_at,u.plan,u.pro_expires_at,s.expires_at FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=?").bind(h).first();if(!u||Date.parse(u.expires_at)<=Date.now()){if(u)await env.DB.prepare("DELETE FROM sessions WHERE token_hash=?").bind(h).run();return null;}return u;}

