async function adminAuth(request,env){const me=await current(request,env);if(!me)return {ok:false,response:reply({error:"سجّل الدخول أولاً"},401)};if(me.id!==NEXCHAT_ADMIN_ID)return {ok:false,response:reply({error:"غير مصرح لك"},403)};const token=getCookie(request,"__Host-nexchat_admin");if(!token||token.length>160)return {ok:false,response:reply({error:"أدخل رمز لوحة التحكم أولاً"},401)};await env.DB.prepare("CREATE TABLE IF NOT EXISTS nexchat_admin_sessions(token_hash TEXT PRIMARY KEY,admin_id TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)").run();const hash=await sha(token);const row=await env.DB.prepare("SELECT admin_id FROM nexchat_admin_sessions WHERE token_hash=? AND admin_id=? AND julianday(expires_at)>julianday('now')").bind(hash,NEXCHAT_ADMIN_ID).first();if(!row)return {ok:false,response:reply({error:"انتهت جلسة لوحة التحكم. سجّل الدخول مجدداً."},401)};return {ok:true,me};}
async function ensureAdminTables(env){await env.DB.prepare("CREATE TABLE IF NOT EXISTS nexchat_feedback(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),username TEXT NOT NULL,display_name TEXT NOT NULL,category TEXT NOT NULL CHECK(category IN ('complaint','suggestion')),subject TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'new',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)").run();await env.DB.prepare("CREATE TABLE IF NOT EXISTS nexchat_ads(id TEXT PRIMARY KEY,title TEXT NOT NULL,body TEXT NOT NULL,link_url TEXT,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)").run();await env.DB.prepare("CREATE TABLE IF NOT EXISTS nexchat_profile_views(profile_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,visitor_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,view_date TEXT NOT NULL,viewed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(profile_user_id,visitor_user_id,view_date))").run();await env.DB.prepare("CREATE TABLE IF NOT EXISTS nexchat_admin_sessions(token_hash TEXT PRIMARY KEY,admin_id TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)").run();}
