 if(url.pathname==="/api/security/sessions/revoke"&&request.method==="POST"){if(!originOK(request))return reply({error:"طلب غير صالح"},403);const me=await current(request,env);if(!me)return reply({error:"سجّل الدخول أولاً"},401);let b;try{b=await request.json()}catch{return reply({error:"بيانات غير صالحة"},400)}const token=getCookie(request,"__Host-nexchat_session"),currentHash=token?await sha(token):"";if(b.allOthers===true){await env.DB.prepare("DELETE FROM sessions WHERE user_id=? AND token_hash<>?").bind(me.id,currentHash).run();await env.DB.prepare("INSERT INTO activity_log(id,user_id,event_type,detail) VALUES(?,?,?,?,?)".replace("VALUES(?,?,?,?,?)","VALUES(?,?,?,?)")).bind(crypto.randomUUID(),me.id,"sessions_revoked","تسجيل الخروج من جميع الأجهزة الأخرى").run();return reply({ok:true});}const target=String(b.sessionId||"");if(!/^[a-f0-9]{64}$/i.test(target)||target===currentHash)return reply({error:"اختر جلسة أخرى صالحة"},400);const result=await env.DB.prepare("DELETE FROM sessions WHERE token_hash=? AND user_id=?").bind(target,me.id).run();if(!result.meta?.changes)return reply({error:"الجلسة غير موجودة"},404);await env.DB.prepare("INSERT INTO activity_log(id,user_id,event_type,detail) VALUES(?,?,?,?)").bind(crypto.randomUUID(),me.id,"session_revoked","تم إنهاء جلسة على جهاز آخر").run();return reply({ok:true});}
